def mirror_with_flip(grid):
    """Mirror and flip content rows"""
    h_seps = sorted([(i, list(set(row))[0]) for i, row in enumerate(grid) if len(set(row)) == 1])

    if not h_seps:
        return [row[:] for row in grid]

    output = [[None]*len(grid[0]) for _ in range(len(grid))]

    # Start with input
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            output[r][c] = grid[r][c]

    from collections import Counter
    all_vals = [grid[r][c] for r in range(len(grid)) for c in range(len(grid[0]))]
    background = max(Counter(all_vals).items(), key=lambda x: x[1])[0]

    for src_r in range(len(grid)):
        for src_c in range(len(grid[0])):
            val = grid[src_r][src_c]

            if val == background:
                continue

            # Reflect across each separator, flipping both horizontally and vertically
            for sep_r, sep_val in h_seps:
                ref_r = 2 * sep_r - src_r
                ref_c = (len(grid[0]) - 1) - src_c  # Horizontal flip

                if 0 <= ref_r < len(grid) and 0 <= ref_c < len(grid[0]):
                    output[ref_r][ref_c] = val

    return output

